import{z as A,x as d,o as E,c as B,q as n,j as r,D as l,d as i,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const y=JSON.parse('{"title":"Kyle 在均衡框架中的位置","description":"","frontmatter":{"title":"Kyle 在均衡框架中的位置","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kyle-in-equilibrium.md","filePath":"econ/kyle-in-equilibrium.md","lastUpdated":1791063341000}'),p={name:"econ/kyle-in-equilibrium.md"};function m(u,a,b,h,c,D){const t=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=n('<h1 id="kyle-在均衡框架中的位置" tabindex="-1">Kyle 在均衡框架中的位置 <a class="header-anchor" href="#kyle-在均衡框架中的位置" aria-label="Permalink to &quot;Kyle 在均衡框架中的位置&quot;">​</a></h1><div class="epigraph"><p>知情者若能影响价格，他就不会把信号一次用尽；均衡价格冲击衡量的是战略泄漏，不是竞争性加总。</p><footer>—— Kyle, Continuous Auctions and Insider Trading, Econometrica, 1985</footer></div><p><a href="/econ/morris-shin-public-info">上一课</a>的人把价格与公告当参数，只在权重上战略。本课缺口是<strong>市场力</strong>：一个知情者选择需求量，\\(p\\) 随他的单子动。Hellwig 的连续统在此失效。不重写限价簿几何，不把 \\(\\lambda\\) 写成盘口回归——协议在 <a href="/econ/to-limit-order-book">到限价簿</a> 之后换栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞争性 REE：每人价格接受，信息经由加总泄漏。Kyle（1985）：一名风险中性知情者看见 \\(\\theta\\)，噪声交易外生，做市商（或竞争型做市端）按订单流的条件期望定价。知情者预见到自己的单子进入总流，因而选择「用多少信号」。线性均衡里 \\(p=\\mu+\\lambda y\\)，\\(y\\) 为总单，\\(\\lambda\\) 是价格冲击系数。知情者最优把泄漏摊开，使 \\(p\\) 对 \\(\\theta\\) 的回归系数停在一半（静态批量）或沿时间均匀释放（连续拍卖）。</p><p>缺口是给这套对象定位：它是战略 REE，不是 Hellwig 的竞争版，也还不是簿上的价格优先。\\(\\lambda\\) 在本栏是逆需求斜率，在量化栏才会变成可估计的冲击。本课只保留均衡陈述。</p><p><span class="marginnote">Kyle, <em>Econometrica</em> 53(6), 1985。批量版本先钉 \\(\\lambda\\)；连续时间版本说明泄漏可以是过程。做市端风险中性、有效定价，是为了把不利选择从存货里分开。</span></p><p><span class="marginnote">术语翻译：\\(\\lambda\\) 就是「我的单子每多 1 份，价格被推高多少」——单子越大，自己的成交价越差。类比卖房：挂 1 套是正常价，一次甩 10 套，买家立刻压价。\\(\\lambda\\) 越大市场越「浅」，大单越不敢下；\\(\\lambda^{-1}\\) 就是本课说的「深度」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三套均衡。Hellwig：价格接受、部分揭示来自供给噪声。GS：采集比例内生，仍是价格接受。Kyle：知情者人数少到必须内部化 \\(\\partial p/\\partial x\\)。噪声交易在此扮演与 \\(z\\) 类似的角色——没有它，做市端从 \\(y\\) 里完全读出 \\(\\theta\\)，知情者不敢交易，市场关闭（与 GS 的精神同构，通道换成战略）。</p><p>线性猜测再次给出闭式。揭示深度由噪声交易方差与信号精度决定：噪声越多，\\(\\lambda\\) 越低，知情者交易越猛，价格里最终仍可有一块 \\(\\theta\\)。这与「流动性越好、信息进入越快」是同一句话的两面，但流动性在本课是 \\(\\lambda^{-1}\\)，不是买卖档位。</p>',11)),(E(),r(s,null,{default:l(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HELL%5B%22Hellwig%3A%20%E4%BB%B7%E6%A0%BC%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%E6%B3%84%E6%BC%8F%22%5D%0A%20%20KYLE%5B%22Kyle%3A%20%E5%86%85%E9%83%A8%E5%8C%96%20dp%2Fdx%22%5D%20--%3E%20STR%5B%22%E6%88%98%E7%95%A5%E6%B3%84%E6%BC%8F%22%5D%0A%20%20STR%20--%3E%20LAM%5B%22%CE%BB%3A%20%E9%80%86%E9%9C%80%E6%B1%82%E6%96%9C%E7%8E%87%22%5D%0A%20%20LOB%5B%22%E9%99%90%E4%BB%B7%E7%B0%BF%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20QUANT%5B%22%E6%8D%A2%E6%A0%8F%3A%20%E9%98%9F%E5%88%97%E4%B8%8E%E6%A1%A3%E4%BD%8D%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"后课不对称信息与流动性，会把 \\(\\lambda\\) 读成不利选择溢价。本课先不要价差分解，也不要存货模型。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"为什么重要（噪声交易）：若没有噪声交易，做市商从订单流里能完整读出知情者的信号，知情者预见到这点就不敢下单，市场直接关闭。噪声交易者是「捣乱因子」——正因为总单里混着无意义的量，做市商只能按条件期望定价，知情者才有藏身之处。这与 GS 的精神同构。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是垄断信息的跨状态套利受到自己价格冲击的约束。多交易一单位，多赚 \\(\\theta-p\\)，也把 \\(p\\) 推向 \\(\\theta\\)，吃掉剩余。均衡卡在边际租金等于边际冲击。连续统把冲击洗成零，知情者变回价格接受者，回到 Hellwig。因此 Kyle 不是「更真实的 Hellwig」，是另一端：\\(N=1\\)（或有限）对 \\(N=\\infty\\)。",-1)),(E(),r(s,null,{default:l(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20MORE%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E5%A4%9A%E4%B8%8B%201%20%E5%8D%95%22%5D%20--%3E%20GAIN%5B%22%E5%A4%9A%E8%B5%9A%20theta%20%E5%87%8F%20p%22%5D%0A%20%20MORE%20--%3E%20PUSH%5B%22%E6%8A%8A%20p%20%E6%8E%A8%E5%90%91%20theta%22%5D%0A%20%20PUSH%20--%3E%20EAT%5B%22%E5%90%83%E6%8E%89%E8%87%AA%E5%B7%B1%E7%9A%84%E5%89%A9%E4%BD%99%22%5D%0A%20%20GAIN%20--%3E%20EQM%5B%22%E5%9D%87%E8%A1%A1%3A%20%E8%BE%B9%E9%99%85%E7%A7%9F%E9%87%91%20%3D%20%E8%BE%B9%E9%99%85%E5%86%B2%E5%87%BB%22%5D%0A%20%20EAT%20--%3E%20EQM%0A%20%20NUP%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E4%BA%BA%E6%95%B0%20N%20%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20WASH%5B%22%E5%86%B2%E5%87%BB%E8%A2%AB%E6%91%8A%E8%96%84%E8%B6%8B%E4%BA%8E%E9%9B%B6%22%5D%0A%20%20WASH%20--%3E%20PTAKER%5B%22%E5%8F%98%E5%9B%9E%E4%BB%B7%E6%A0%BC%E6%8E%A5%E5%8F%97%3A%20Hellwig%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>不要把噪声交易者写成行为金融的 DSSW：这里他们是外生需求，没有效用，只为了让做市端的推断有残差。行为课已经写过噪声交易者风险；本课借用噪声当残差不确定性。</p><p><span class="marginnote">多知情者、风险厌恶知情者、离散出价，会改 \\(\\lambda\\) 的公式，不改「战略泄漏」这一刀。Back、Holden–Subrahmanyam 是同一框架的延伸，本课不展开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>量化栏会估计价格冲击、买卖价差、订单流毒性。本课禁止把那些回归表写进来，也禁止画簿。\\(\\lambda\\) 不是 tick 上的弹性。下一课把战略与竞争两头收成一句理论：不对称信息本身可以定义流动性成本，无需队列。</p><p><span class="marginnote">常见误区：把 Kyle 说成「更真实的 Hellwig」。两者是光谱两端：\\(N=\\infty\\) 时每人的冲击被洗成零、回到价格接受；\\(N=1\\) 时冲击必须内部化。要谈极限，得说清 \\(N\\) 与噪声如何一起缩放，不能拿「多加几个人就变回竞争」当口头禅。</span></p><p>后课默认：Kyle 是有市场力的 REE；\\(\\lambda\\) 是战略逆需求；噪声交易防止市场关闭。竞争性部分揭示是 Hellwig，不是 Kyle 的极限口头禅能替代的——极限要看 \\(N\\) 与噪声如何一起缩放。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>知情者内部化价格冲击时，泄漏是战略选择，不是竞争性加总。</li><li>\\(\\lambda\\) 是本栏的逆需求，不是盘口回归。</li><li>与 GS 同构的是「无噪声则无交易」；通道不同。</li><li>出处：Kyle, <em>Econometrica</em> 1985；对照 Hellwig 1980。</li></ul>',8))])}const g=A(p,[["render",m]]);export{y as __pageData,g as default};
